 k_fam:['Families ticked','Familia zilizochaguliwa'],k_prod:['Products to stock','Bidhaa za kuweka'],k_inv:['Opening stock at cost','Bidhaa za kuanzia kwa gharama'],k_sales:['Sales in %M','Mauzo %M'],k_gp:['Gross profit in %M','Faida ghafi %M'],k_gm:['Gross margin','Kiwango cha faida'],k_shelf:['Shelf space','Nafasi ya rafu'],k_wh:['Warehouse locations','Sehemu za ghala'],k_cover:['Stock cover','Muda wa stoo'],
