// ---- buying desk ----
const COVER={hero:2,core:3,season:4,special:4},FW={s:.08,m:.16,l:.32,xl:0},PERF={s:3,m:2,l:1,xl:1},LOC={s:40,m:12,l:30,xl:1};
function mult(f,m){const act=MSEA[m].filter(s=>s!=='gift'||m===4||m===11);const ins=f.season.some(s=>act.includes(s)),all=f.season.includes('all');return ins?(all?1.25:1.6):(all?1:.35)}
function calc(fams,m,depth){const seen=new Set();const r={f:0,p:0,inv:0,sales:0,cogs:0,shelf:0,floor:0,bins:0,cart:0,pal:0,fl:0,z:{}};
 fams.forEach(f=>{const mu=mult(f,m),cov=COVER[f.tier];const zr=r.z[f.z]=r.z[f.z]||{f:0,p:0,inv:0,sales:0,gp:0,shelf:0};r.f++;zr.f++;
  f.p.forEach(j=>{const p=LIB.P[j];if(!depth&&p[9]!==0&&p[9]!==1)return;if(seen.has(j))return;seen.add(j);const u=p[10]*mu,cf=CF[p[8]],face=f.tier==='hero'&&(p[9]===0)?2:1;
   const disp=(p[4]>=40000||(f.handle||[]).includes('high_value'))?1:face*PERF[f.size],stock=Math.max(disp,Math.ceil(u*cov/4.345)),back=Math.max(0,stock-disp);
   const inv=stock*p[4]*cf,sal=u*p[4],cg=sal*cf;r.p++;zr.p++;r.inv+=inv;zr.inv+=inv;r.sales+=sal;zr.sales+=sal;r.cogs+=cg;zr.gp+=sal-cg;
   if(f.size==='xl'){r.floor+=1;r.fl+=back}else{const sh=face*FW[f.size];r.shelf+=sh;zr.shelf+=sh;if(f.size==='s')r.bins+=Math.ceil(back/LOC.s);else if(f.size==='m')r.cart+=Math.ceil(back/LOC.m);else r.pal+=back/LOC.l}})});
 r.pal=Math.ceil(r.pal);r.gp=r.sales-r.cogs;return r}
function desk(){const g=id=>document.getElementById(id);const host=g('r6desk');if(!host)return;let showAll=false;
 host.innerHTML=`<div class="r6desk">${deskGuide()}<div class="r6dctl"><div><span class="lb">${U('month')}</span><div class="r6mo" id="r6mo">${MONTHS.map((m,i)=>`<button type="button" data-m="${i}">${L(m)}</button>`).join('')}</div></div><div><span class="lb">${U('preset')}</span><div class="r6seg" id="r6pr"><button type="button" data-p="win">${U('p_win')}</button><button type="button" data-p="launch">${U('p_launch')}</button><button type="button" data-p="full">${U('p_full')}</button><button type="button" data-p="none">${U('p_none')}</button></div></div><div><span class="lb">${U('depth')}</span><div class="r6seg" id="r6dp"><button type="button" data-d="0">${U('d_lean')}</button><button type="button" data-d="1">${U('d_full')}</button></div></div></div>
 <div class="r6kp" id="r6kp"></div><div class="r6fit" id="r6fit"></div><div class="r6dbody"><h5>${U('byzone')}</h5><div class="r6tw" id="r6dz"></div><h5>${U('sheet')}</h5><p class="nt" style="margin:0 0 10px">${U('sheet_ld')}</p><div class="r6tw r6sh" id="r6sh"></div><details class="r6d"><summary>${U('rules')}</summary><ul class="r6rl">${U('rules_t')}</ul></details></div></div>`;
 const paint=()=>{const m=S6.month,mn=L(MONTHS[m]);g('r6mo').querySelectorAll('button').forEach(b=>b.classList.toggle('on',+b.dataset.m===m));g('r6dp').querySelectorAll('button').forEach(b=>b.classList.toggle('on',+b.dataset.d===S6.depth));
  const sel=LIB.fams.filter(f=>S6.pick.has(f.k)),r=calc(sel,m,S6.depth);const gm=r.sales?r.gp/r.sales:0,cover=r.cogs?r.inv/r.cogs*4.345:0;
  const K=[['k_fam',r.f,`${U('fams')} · ${LIB.fams.length}`],['k_prod',NF(r.p),`${U('products')}`],['k_inv',TM(r.inv),'',1],['k_sales',TM(r.sales),''],['k_gp',TM(r.gp),'',1],['k_gm',(gm*100).toFixed(1)+'%',''],['k_shelf',`${(r.shelf/5).toFixed(1)}`,U('bays').replace('%B',(r.shelf/5).toFixed(1)).replace('%M',r.shelf.toFixed(1))+(r.floor?' '+U('floor').replace('%F',r.floor):'')],['k_wh',NF(r.bins+r.cart+r.pal+r.fl),U('whl').replace('%S',r.bins).replace('%C',r.cart).replace('%P',r.pal).replace('%F',r.fl)]];
  g('r6kp').innerHTML=K.map(k=>`<div class="${k[3]?'g':''}"><small>${U(k[0]).replace('%M',mn)}</small><b class="fl">${k[1]}</b><span>${k[2]}</span></div>`).join('');const kp=g('r6kp');setTimeout(()=>kp.querySelectorAll('b').forEach(b=>b.classList.remove('fl')),300);
  const sb=r.shelf/5,okS=r.inv<=30e6,okB=sb<=32;
  g('r6fit').innerHTML=`<div class="${okS?'ok':'ov'}"><small>${U('fit_s')}</small><b>${TM(r.inv)} / TSh 30.0 m</b><i><u style="width:${Math.min(100,r.inv/30e6*100).toFixed(1)}%"></u></i></div><div class="${okB?'ok':'ov'}"><small>${U('fit_b')}</small><b>${sb.toFixed(1)} / 32</b><i><u style="width:${Math.min(100,sb/32*100).toFixed(1)}%"></u></i></div><p>${okS&&okB?U('fit_ok'):U('fit_no')}</p>`;
  g('r6dz').innerHTML=`<table class="r6tbl"><thead><tr><th>${U('th_zone')}</th><th class="n">${U('th_fam')}</th><th class="n">${U('th_prod')}</th><th class="n">${U('th_inv')}</th><th class="n">${U('th_sales')} · ${mn}</th><th class="n">${U('th_gp')}</th><th class="n">${U('th_shelf')}</th></tr></thead><tbody>${ZK.map(k=>{const z=r.z[k]||{f:0,p:0,inv:0,sales:0,gp:0,shelf:0};return `<tr><td><b style="color:${ZC[k]}">${E(L(ZS(k).n))}</b></td><td class="n">${z.f}</td><td class="n">${NF(z.p)}</td><td class="n">${TM(z.inv)}</td><td class="n">${TM(z.sales)}</td><td class="n">${TM(z.gp)}</td><td class="n">${z.shelf.toFixed(1)}</td></tr>`}).join('')}<tr><td><b>${lang()?'Jumla':'Total'}</b></td><td class="n"><b>${r.f}</b></td><td class="n"><b>${NF(r.p)}</b></td><td class="n"><b>${TM(r.inv)}</b></td><td class="n"><b>${TM(r.sales)}</b></td><td class="n"><b>${TM(r.gp)}</b></td><td class="n"><b>${r.shelf.toFixed(1)}</b></td></tr></tbody></table><p class="nt" style="margin:10px 12px">${U('k_cover')}: <b>${U('weeks').replace('%W',cover.toFixed(1))}</b> · ${lang()?'mzunguko wa stoo':'stock turns'} <b>${cover?(52/cover).toFixed(1):'–'}×</b> ${lang()?'kwa mwaka':'a year'}</p>`;
  const rows=LIB.fams.map(f=>{const one=calc([f],m,S6.depth);return {f,one,mu:mult(f,m)}}).sort((a,b)=>(S6.pick.has(b.f.k)-S6.pick.has(a.f.k))||b.one.sales-a.one.sales);
  const vis=showAll?rows:rows.slice(0,60);
  g('r6sh').innerHTML=`<table class="r6tbl"><thead><tr><th></th><th>${U('th_f')}</th><th>${U('role')}</th><th class="n">${U('th_prod')}</th><th class="n">${U('th_sales')} · ${mn}</th><th class="n">${U('th_cost')}</th><th class="n">${U('th_gp')}</th></tr></thead><tbody>${vis.map(({f,one,mu})=>`<tr class="${S6.pick.has(f.k)?'':'off'}"><td><input type="checkbox" data-k="${f.k}" ${S6.pick.has(f.k)?'checked':''} aria-label="${E(L(f.n))}"></td><td class="f"><span class="tile" style="${TL(f.im)}"></span><span><b style="cursor:pointer" data-o="${f.k}">${E(L(f.n))}</b>${mu>1?`<span class="r6pk">${U('peak')}</span>`:''}<small style="color:${ZC[f.z]}">${E(L(ZS(f.z).n))}</small></span></td><td>${L(TIER[f.tier])}</td><td class="n">${one.p}</td><td class="n">${TM(one.sales)}</td><td class="n">${TM(one.inv)}</td><td class="n">${TM(one.gp)}</td></tr>`).join('')}</tbody></table>${showAll?'':`<button type="button" class="r6more" id="r6sa" style="margin:12px auto">${U('showall').replace('%N',rows.length)}</button>`}`;
  const sa=g('r6sa');if(sa)sa.onclick=()=>{showAll=true;paint()};deskX()};
 g('r6sh').addEventListener('change',e=>{const k=e.target.dataset.k;if(!k)return;togglePick(k);if(window.__r6list)window.__r6list()});
 g('r6sh').addEventListener('click',e=>{const k=e.target.dataset.o;if(k)openFam(LIB.fams.find(f=>f.k===k))});
 g('r6mo').querySelectorAll('button').forEach(b=>b.onclick=()=>{S6.month=+b.dataset.m;paint()});
 g('r6dp').querySelectorAll('button').forEach(b=>b.onclick=()=>{S6.depth=+b.dataset.d;paint()});
 g('r6pr').querySelectorAll('button').forEach(b=>b.onclick=()=>{const p=b.dataset.p;S6.pick=new Set(p==='win'?win100():p==='launch'?LIB.fams.filter(f=>f.tier==='hero'||f.tier==='core').map(f=>f.k):p==='full'?LIB.fams.map(f=>f.k):[]);paint();if(window.__r6list)window.__r6list()});
 let tm=0;window.__r6desk=()=>{clearTimeout(tm);tm=setTimeout(()=>{if(document.getElementById('r6mo')===g0)paint()},60)};const g0=g('r6mo');paint()}

