  const lead=act[0],s=SEA[lead];const seen=new Set(),isl=[];act.forEach(k=>(SUM.sea[k]||[]).forEach(f=>{if(!seen.has(f.k)&&isl.length<12){seen.add(f.k);isl.push(f)}}));
