let LQ='',LSEL=null;
function locate(){const out={};LIB.fams.forEach(f=>{});
 ZK.forEach(z=>{const B=bays(z),cap=Math.round(((window.FP&&FP.AREAS.find(a=>a.k===z))||{m:8}).m);B.forEach((b,bi)=>b.forEach((sh,si)=>sh.it.forEach(it=>{out[it.j]={z,bay:bi+1,shelf:si+1,cap,on:bi<cap}})))});
 // stockroom slot: rank by monthly sales within the zone
 ZK.forEach(z=>{const ps=[];LIB.fams.filter(f=>f.z===z).forEach(f=>f.p.forEach(j=>{if(!ps.includes(j))ps.push(j)}));ps.sort((a,b)=>LIB.P[b][4]*LIB.P[b][10]-LIB.P[a][4]*LIB.P[a][10]).forEach((j,i)=>{(out[j]=out[j]||{z})._slot=i+1})});return out}
let LOCS=null;
function locator(){const g=id=>document.getElementById(id);if(!g('r6lq'))return;const X=k=>L(KX[k]);LOCS=LOCS||locate();
 const list=()=>{const q=LQ.trim().toLowerCase().split(/\s+/).filter(Boolean);const hits=[];
  if(q.length)LIB.P.forEach((p,j)=>{const f=LIB.fams[p[0]];const t=(p[1]+' '+p[2]+' '+p[3]+' '+f.n[0]+' '+f.n[1]).toLowerCase();if(q.every(w=>t.includes(w)))hits.push(j)});
  const on=j=>(LOCS[j]&&LOCS[j].on)?0:1;hits.sort((a,b)=>on(a)-on(b)||LIB.P[a][9]-LIB.P[b][9]||LIB.P[b][4]*LIB.P[b][10]-LIB.P[a][4]*LIB.P[a][10]);const H=hits.slice(0,40);
  g('r6lres').innerHTML=q.length?(H.length?H.map(j=>{const p=LIB.P[j],f=LIB.fams[p[0]],lc=LOCS[j]||{};return `<button type="button" data-j="${j}" class="${j===LSEL?'on':''}"><span class="tile" style="${TL(f.im)}"></span><span><b>${E(p[1])}</b><small>${E(p[3])} · ${T(p[4])}</small></span><em>${code(j)}</em></button>`}).join('')+(hits.length>40?`<p class="nt">${hits.length-40} ${L(['more, refine the search','zaidi, boresha utafutaji'])}</p>`:''):`<p class="nt">${U('none')}</p>`):'';
  g('r6lres').querySelectorAll('button').forEach(b=>b.onclick=()=>{LSEL=+b.dataset.j;list();card()})};
 const code=j=>{const lc=LOCS[j]||{},p=LIB.P[j],f=LIB.fams[p[0]];const z=lc.z||f.z;if(f.size==='xl')return ZL[z]+'-FLOOR';return lc.bay&&lc.on?`${ZL[z]}-${String(lc.bay).padStart(2,'0')}-${lc.shelf}`:`${ZL[z]}-S${String(lc._slot||0).padStart(3,'0')}`};
 const card=()=>{const j=LSEL;if(j==null){g('r6lcard').innerHTML='';return}const p=LIB.P[j],f=LIB.fams[p[0]],lc=LOCS[j]||{},z=f.z,a=window.FP&&FP.AREAS.find(x=>x.k===z);
  const shopTxt=f.size==='xl'?L(['One floor model in the zone','Mfano mmoja sakafuni kwenye kanda']):lc.on?X('bay').replace('%B',lc.bay).replace('%C',lc.cap).replace('%S',L(UX6.sh[lc.shelf-1])):X('beyond');
  const typ=f.size==='s'?X('bins'):f.size==='m'?X('cart'):f.size==='l'?X('pal'):X('flr');
  const ord=f.size==='xl'?X('o_floor'):lc.on?X('o_shelf'):X('o_back');
  let pt=null;if(a){const [x1,y1,x2,y2]=a.r;const vert=(y2-y1)>(x2-x1);if(f.size==='xl'||!lc.on){pt=f.size==='xl'?[(x1+x2)/2,(y1+y2)/2]:[672,72]}else{const t=(lc.bay-.5)/lc.cap;pt=vert?[(x1+x2)/2,y2-t*(y2-y1)]:[x1+t*(x2-x1),(y1+y2)/2]}}
  g('r6lcard').innerHTML=`<div class="r6lc"><div class="top"><span class="tile" style="${TL(f.im)}"></span><div><h4>${E(p[1])}</h4><p>${E(p[2])} · ${E(p[3])} · ${T(p[4])}</p><p style="color:${ZC[z]}">${E(L(ZS(z).n))} · ${E(L(f.n))}</p><span class="code">${code(j)}</span></div></div>
   <dl><dt>${X('shop')}</dt><dd>${shopTxt}</dd><dt>${X('stock')}</dt><dd>${X('rack').replace('%R',ZL[z]).replace('%T',typ).replace('%N',lc._slot||'–')}</dd><dt>${X('order')}</dt><dd>${ord}</dd></dl>
   ${pt?`<div class="r6lmap"><img src="img/s-plan.webp" alt="Concept plan of the store with the product location marked"><svg viewBox="0 0 1280 720" preserveAspectRatio="none"><rect x="${a.r[0]}" y="${a.r[1]}" width="${a.r[2]-a.r[0]}" height="${a.r[3]-a.r[1]}" fill="${ZC[z]}" fill-opacity=".18" stroke="${ZC[z]}" stroke-width="3"/><circle cx="${pt[0]}" cy="${pt[1]}" r="34" fill="${ZC[z]}" opacity=".3"><animate attributeName="r" values="20;42;20" dur="1.8s" repeatCount="indefinite"/></circle><circle cx="${pt[0]}" cy="${pt[1]}" r="15" fill="${ZC[z]}" stroke="#101311" stroke-width="4"/></svg></div>`:''}</div>`};
 g('r6lq').oninput=e=>{LQ=e.target.value;list()};
 if(!LQ){LQ=lang()?'nepi':'nappies';g('r6lq').value=LQ}list();if(LSEL==null){const b=g('r6lres').querySelector('button');if(b){LSEL=+b.dataset.j;list();card()}}else card()}
function locHTML(){kcss();const X=k=>L(KX[k]);return [X('m_loc'),`<p class="ld">${X('loc_ld')}</p><div class="r6how">${KX.howt.map(x=>`<div><b>${L(x[0])}</b><p>${L(x[1])}</p></div>`).join('')}</div><div class="r6loc"><div><input class="r6sel" type="search" id="r6lq" placeholder="${E(X('locq'))}" aria-label="${E(X('locq'))}"><div class="r6lr" id="r6lres"></div></div><div id="r6lcard"></div></div>`,'r6m-loc']}
const EXLOC={w:['A product locator. Every product has one address in the store and one in the stockroom, written as a short code, so customers, advisers and pickers all use the same map.','Kitafutaji cha bidhaa. Kila bidhaa ina anwani moja dukani na moja stoo, iliyoandikwa kama msimbo mfupi, ili wateja, washauri na wachukuaji wote watumie ramani moja.'],
 r:['Search for a product or a need. Each result shows its code. Open one to see the bay and shelf in the store, the rack and slot in the stockroom, how a customer gets it if it is not on the floor, and a dot on the store plan. A code such as D-03-2 means zone D (Heart & Diabetes), bay 3, shelf 2; D-S014 means stockroom rack D, slot 14.','Tafuta bidhaa au hitaji. Kila tokeo linaonyesha msimbo wake. Fungua moja kuona rafu na ngazi dukani, rafu na nafasi stoo, jinsi mteja anavyoipata isipokuwa sakafuni, na nukta kwenye ramani ya duka. Msimbo kama D-03-2 unamaanisha kanda D (Moyo na Kisukari), rafu 3, ngazi 2; D-S014 inamaanisha rafu ya stoo D, nafasi 14.'],
 m:['A store with 2,810 products only works if anyone can find any of them in seconds. One address system cuts picking time for Afya Box orders, lets a new adviser answer “where is it?” on day one, and makes the nightly restock a list of codes rather than a search.','Duka lenye bidhaa 2,810 linafanya kazi tu kama mtu yeyote anaweza kupata yoyote kwa sekunde chache. Mfumo mmoja wa anwani unapunguza muda wa kuchukua oda za Afya Box, unamwezesha mshauri mpya kujibu “iko wapi?” siku ya kwanza, na unafanya kujaza rafu kila usiku kuwa orodha ya misimbo badala ya kutafuta.']};
